/** A proof was added to a claim on a sheet, giving it the proofs count. The number is the claim's number. */
public record ClaimProofAdded(String sheetId, String user, String person, BigDecimal amount, LocalDate date,
        String number, int proofs) {
}
-- A claim's comments, oldest first: each with the user who wrote it and the sheet's today when it was
-- written. A claim already there starts with none.
CREATE TABLE claim_comment (
    claim_id BIGINT NOT NULL REFERENCES claim(id),
    seq INT NOT NULL,
    by_user VARCHAR(200) NOT NULL,
    on_date DATE NOT NULL,
    text VARCHAR(1000) NOT NULL,
    PRIMARY KEY (claim_id, seq)
);
-- A person's tags: trimmed, lower-cased, without repeats, sorted and comma separated; '' when they have none.
ALTER TABLE person ADD COLUMN tags VARCHAR(1000) NOT NULL DEFAULT '';

